import fs from 'fs';
import { getNotesPath } from './config.js';

type NoteStore = { commits: Record<string, string[]> };

function load(): NoteStore {
  const file = getNotesPath();
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8')) as NoteStore;
  } catch {
    return { commits: {} };
  }
}

function save(store: NoteStore) {
  fs.writeFileSync(getNotesPath(), JSON.stringify(store, null, 2));
}

export function addCommitNote(hash: string, note: string) {
  const store = load();
  store.commits[hash] = store.commits[hash] || [];
  store.commits[hash].push(note);
  save(store);
}

export function getCommitNotes(hash: string) {
  const store = load();
  return store.commits[hash] || [];
}
